// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes4 constant IACCESSCONTROL_ID = 0x7965db0b;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 seed) public {
        // For every 4-byte selector s, supportsInterface(s) must equal
        // (s == IAccessControl interfaceId || s == IERC165 interfaceId).
        // We check the IAccessControl part of the rule; the mutant replaced it
        // with IERC165 (already covered by super), so it returns false for it.
        assertTrue(c.supportsInterface(IACCESSCONTROL_ID), "must support IAccessControl");
    }
}
